<template>
    <div class="layout-px-spacing">  
        <ul class="navbar-nav flex-row mt-2">
            <li>
                <div class="page-header">
                    <nav class="breadcrumb-one" aria-label="breadcrumb">
                        <ol class="breadcrumb">
                            <li class="breadcrumb-item"><a href="javascript:;">Masters</a></li>
                            <li class="breadcrumb-item active" aria-current="page"><span> Assets Readings </span></li>
                        </ol>
                    </nav>
                </div>
            </li>
        </ul>

        <h5 class="text-center">VEHICLE AND MACHINE SERVICE FREQUENCY</h5>

                <div class="d-flex me-4 mt-2 ">
                        <div class="ms-auto">
                            <button class="btn btn-primary " @click="service_frequency =! service_frequency">                           
                                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" fill="currentColor" class="bi bi-plus-square" viewBox="0 0 16 16">
  <path d="M14 1a1 1 0 0 1 1 1v12a1 1 0 0 1-1 1H2a1 1 0 0 1-1-1V2a1 1 0 0 1 1-1zM2 0a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V2a2 2 0 0 0-2-2z"/>
  <path d="M8 4a.5.5 0 0 1 .5.5v3h3a.5.5 0 0 1 0 1h-3v3a.5.5 0 0 1-1 0v-3h-3a.5.5 0 0 1 0-1h3v-3A.5.5 0 0 1 8 4"/>
</svg>
</button>
 
                        </div>
                    </div>

                             <!-- item registration form starts -->
 <form v-if="service_frequency" class="mt-3 p-3 border rounded bg-white shadow" @submit.prevent="registerServiceFrequency()">
        <h6 class="text-center">REGISTER ASSET SERVICE FREQUENCY</h6>
       <div class="row mb-3">
                <div class="col-md-4">
                <label for="name">asset</label>
                 <multiselect 
                v-model="asset_id"
                :options= "assets"
                placeholder="Select An Asset"
                label="name"
                :searchable = "true"        
                multple="false"
                :required="true"
                :allow-empty="false"
            ></multiselect>
            </div>
            <div class="col-md-4">
                <label for="name">Master Service</label>
                 <multiselect 
                v-model="service"
                :options= "services"
                placeholder="Select Service"
                label="name"
                :searchable = "true"        
                multple="false"
                :required="true"
                :allow-empty="false"
            ></multiselect>
            </div>
            <div class="col-md-4">
            <label class="form-label small">Reading Unit</label>
            <multiselect 
                v-model="unit"
                :options= "unitList"
                placeholder="select unit"
                label="short_name"
                :searchable = "true"        
                multple="false"
                :required="true"
                :allow-empty="false"
            ></multiselect>
        </div>
            <div class="col-md-6">
                <label for="quantity">Frequency Reading</label>
              <input type="number" v-model="reading" class="form-control" placeholder="Enter Quantity" min="1" required>
            </div>
            <div class="col-md-6">
                <label for="quantity">Alert When Reaches</label>
              <input type="number" v-model="remainder" class="form-control" placeholder="Enter Quantity" min="1" required>
            </div>
          </div>
        <div class="text-center gap-2 justify-content-end">
            <button type="button" class="btn btn-danger me-3" @click="service_frequency = false; resetForm();">Cancel</button>
             <button type="submit" class="btn btn-primary" :disabled="submitting">
                <span v-if="submitting" class="spinner-border spinner-border-sm text-white me-2" role="status"></span>
                Register
            </button>
        </div>
    </form>
             <!-- item registration form ends-->

              <!-- loading spinner starts -->
        <div v-if="loading_spinner" v-html="tableShimmer()"></div>
        <!-- Loading spinner ends -->
        <div v-else class="row layout-top-spacing">
            <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
                <div class="panel p-0">
                    <div class="custom-table table3">
                        <v-client-table :data="asset" :columns="columns" :options="table_option">
                            <template #actions="props">
                              
                                <a href="javascript:;" class="edit me-3" @click="openEditModal(props.row)" data-bs-toggle="modal" :data-bs-target="'#edit-modal'">
                                   <i class="bi bi-pencil-square text-primary  fs-4"></i>
                                </a>
                               
                            </template>
                        </v-client-table>
                    </div>
                </div>
            </div>
        </div>


<div class="modal fade mymodal" id="edit-modal" data-bs-backdrop="false" data-bs-keyboard="false" tabindex="-1" aria-labelledby="editConversionFactorModalLabel" aria-hidden="true">
  <div class="modal-dialog modal-xl">
    <div class="modal-content">
      <div class="modal-header">
        <h1 class="modal-title fs-5" id="editConversionFactorModalLabel">Edit Asset Service Frequency</h1>
        <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close" @click="resetForm(); "></button>
      </div>
      <form @submit.prevent="updateAssetServiceFrequency()">
        <div class="modal-body">
            <div class="row mb-3">
            <div class="col-md-4">
                <label for="name">asset</label>
                 <multiselect 
                v-model="asset_id"
                :options= "assets"
                placeholder="Select An Asset"
                label="name"
                :searchable = "true"        
                multple="false"
                :required="true"
                :allow-empty="false"
            ></multiselect>
            </div>
            <div class="col-md-4">
                <label for="name">Master Service</label>
                 <multiselect 
                v-model="service"
                :options= "services"
                placeholder="Select Service"
                label="name"
                :searchable = "true"        
                multple="false"
                :required="true"
                :allow-empty="false"
            ></multiselect>
            </div>
            <div class="col-md-4">
            <label class="form-label small">Reading Unit</label>
            <multiselect 
                v-model="unit"
                :options= "unitList"
                placeholder="select unit"
                label="short_name"
                :searchable = "true"        
                multple="false"
                :required="true"
                :allow-empty="false"
            ></multiselect>
        </div>
            <div class="col-md-6">
                <label for="quantity">Frequency Reading</label>
              <input type="number" v-model="reading" class="form-control" placeholder="Enter Quantity" min="1" required>
            </div>
            <div class="col-md-6">
                <label for="quantity">Alert When Reaches</label>
              <input type="number" v-model="remainder" class="form-control" placeholder="Enter Quantity" min="1" required>
            </div>
          </div>
        </div>
        <div class="modal-footer">
          <button type="button" class="btn btn-secondary" data-bs-dismiss="modal" @click="closeEditModal()" id="close_editing">Close</button>
          <button type="submit" class="btn btn-primary" :disabled="submitting">
            <span v-if="submitting" class="spinner-border spinner-border-sm text-white me-2" role="status"></span>
            Edit
          </button>
        </div>
      </form>
    </div>
  </div>
</div>

      
    </div>
</template>



<script setup>
    import { onMounted, ref, inject } from 'vue';
    import axios from 'axios';
    import { useMeta } from '@/composables/use-meta';
    import Multiselect from '@suadelabs/vue3-multiselect';
    import '@suadelabs/vue3-multiselect/dist/vue3-multiselect.css';
    
    useMeta({ title: 'Asset Service Frequency' });  
        const service_frequency = ref(false);

    const showMessage = inject('showMessage');
    const showError = inject('showError');
    const user_permissions = JSON.parse(localStorage.getItem("user")).permissions;
     const formatNumber = inject('formatNumber');
    const tableShimmer = inject('tableShimmer');
    
    const loading_spinner = ref(false);
    const columns = ref(['SNo','name', 'service','reading_unit','frequency_reading','alert_when_reaches','actions']);    
    const asset = ref([]);

    
    const table_option = ref({
        perPage: 20,
        perPageValues: [20, 50 ,100],
        skin: 'table table-hover table-striped',
        columnsClasses: { actions: 'actions text-center' },
        sortable: ['SNo', 'name','short_name','status'],
        sortIcon: {
            base: 'sort-icon-none',
            up: 'sort-icon-asc',
            down: 'sort-icon-desc',
        },
        pagination: { nav: 'scroll', chunk: 5 },
        texts: {
            count: 'Showing {from} to {to} of {count}',
            filter: '',
            filterPlaceholder: 'Search...',
            limit: 'Results:',
        },
        resizableColumns: false,
    });

    const axiosInstance = axios.create({
        baseURL: process.env.VUE_APP_API_BASE_URL
    });


    const getAssetServiceFrequency = async (showLoader = true) => {
        if (showLoader) loading_spinner.value = true;
        try {
            const response = await axiosInstance.get('asset_service_frequencies');
           asset.value = response.data.map((item, index) => ({
    ...item,
    SNo: index + 1,
    id: item?.id,
    name: item?.asset?.make 
        ? `${item.asset.name} - ${item.asset.make}` 
        : item?.asset?.name || '',
    reading_unit: item.unit,
    frequency_reading: formatNumber(item.reading),
    alert_when_reaches: formatNumber(item.remainder),
    service: item?.service?.name
}));
        } catch (error) {
            showError(error.message);
            console.log(error)
        }finally{
            if (showLoader) loading_spinner.value = false;
        }
    };


    const assets= ref([])
const getAssets = async ()=>{
   try {
            const response = await axiosInstance.get('/machines');
            assets.value = response.data;
        } catch (error) {
            showError(error.message);
            console.log(error)
        }
}

    const unitList = ref([]);
    const getUnits = async () => {
        try {
            const response = await axiosInstance.get('/units');
            unitList.value = response.data;
        } catch (error) {
            showError(error.message);
            console.log(error)
        }
    };

     const services = ref([]);
    const getMasterServices = async () => {
        try {
            const response = await axiosInstance.get('/master-services');
            services.value = response.data;
        } catch (error) {
            showError(error.message);
            console.log(error)
        }
    };

const submitting = ref(false);

        const registerServiceFrequency = async () => {
    
        submitting.value = true;
        const itemData = {
           asset_id: asset_id.value.id,
            unit: unit.value.short_name,
            remainder: remainder.value,
            reading: reading.value,
            master_service_id:service.value.id
        };
    
        try {
            const response = await axiosInstance.post('/asset_service_frequencies', itemData);
            getAssetServiceFrequency (false);
            showMessage(' registered successfully!');
            resetForm();
        } catch (error) {
            showError(error.message);
            console.log(error)
        } finally {
            submitting.value = false;
        }
    };    

    const resetForm = () => {
    unit.value = '';
    reading.value = '';
    remainder.value = '';
    service.value = '';
    asset_id.value = '';
    service_frequency.value = false;
};


    const reading = ref('');
    const unit = ref('');
    const remainder = ref('');
    const asset_id = ref('');
    const service = ref('');
    const asset_service = ref('');

const openEditModal = (row) => {
    asset_service.value = row;
    asset_id.value = assets.value.find(a => a.id === row.asset_id) || null;
    reading.value = row.reading;
     unit.value = unitList.value.find(
        u => u.short_name.toLowerCase() === row.reading_unit.toLowerCase()
    ) || null;
    remainder.value = row.remainder;
    service.value = services.value.find(s => s.name === row.service) || null;
};

        const updateAssetServiceFrequency = async () => {
        submitting.value = true;

        const payload = {
           asset_id: asset_id.value.id,
            unit: unit.value.short_name,
            remainder: remainder.value,
            reading: reading.value,
            master_service_id:service.value.id
        };

        try {
            const response = await axiosInstance.put(`/asset_service_frequencies/${asset_service.value.id}`, payload);
           getAssetServiceFrequency (false);
            showMessage('updated successfully!');
            document.getElementById('close_editing').click();
            resetForm();
        } catch (error) {
            showError(error.message);
        } finally {
            submitting.value = false;
        }
    };
    
    onMounted(() => {
        getAssetServiceFrequency();
        getMasterServices();
        getAssets();
        getUnits();
       
    });
</script>